    SELECT
        'INQE'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(INTERVIEW_QUESTION_NO), LENGTH('INQE' ) + 1)), 0) + 1, 6, '0')
    FROM INTERVIEW_QUESTION

	INSERT INTO INTERVIEW_QUESTION (
		INTERVIEW_QUESTION_NO
		, INTERVIEW_NO
		, INTERVIEW_QUESTION_CONTENT
		, INTERVIEW_QUESTION_SCORE
	) VALUES (
		#{interviewQuestionNo}
		, #{interviewNo}
		, #{interviewQuestionContent}
		, #{interviewQuestionScore}
	)

