UPDATE INTERVIEW_QUESTION
SET 
	INTERVIEW_NO = #{interviewNo}
	, INTERVIEW_QUESTION_CONTENT = #{interviewQuestionContent}
	, INTERVIEW_QUESTION_SCORE = #{interviewQuestionScore}
WHERE INTERVIEW_QUESTION_NO = #{interviewQuestionNo}
